rows=[]
for n,r in enumerate(ROWS,1):
    m=re.match(r'(\d{4})',str(r['coronation_date'] or r['concession_date'] or ''))
    rows.append({'no':n,**r,'year':int(m.group(1)) if m else None})
assert len(rows)==74, len(rows)
out={'source':("[Pietro Bombelli, incisore], Raccolta delle immagini della Beatissima Vergine ornate della corona d'oro dal R.mo "
  "Capitolo di S. Pietro, con una breve ed esatta notizia di ciascuna immagine, 4 tomi, Roma, Salomoni, 1792 (plates dated "
  "1791-1793). Tomi II-IV: 74 of the 104 crowned images."),
 'scan':{'II':'https://archive.org/details/bub_gb_JhP2LAUmGjUC','III':'https://archive.org/details/bub_gb_rHbfIRvNjxkC',
         'IV':'https://archive.org/details/bub_gb_9vADu01fhEAC','I':'not found online'},
 'transcribed':'2026-09-14, from the OCR text with every date and number checked against the page image, and every plate caption read from the scan',
 'note':("One row per notice. `coronation_date` is the day the notice gives for the ceremony (or, where it names only the "
  "delivery of the crowns, that day); `concession_date` the decree or petition where given; `child_date` a separate crown "
  "for the Bambino Gesù. `caption_year`, `medium` and `size_palmi` are read from the engraved caption of the facing plate "
  "('in Tavola, Alta Pal. 4, Lar. 3, Coronata dal R.mo Capitolo di S. Pietro in Vatic. nel 1655'). `crown_cost_scudi` and "
  "`deputies` are as the notice gives them. `locality` is in the catalogue's own form so that Bombelli's image meets "
  "Briccolani's; `title` is the devotional title alone, the church being carried by `church_or_place`. Where the plate and "
  "the notice disagree on the year (Vittoria, Sole, Minerva, Prassede) the notice's date is kept and the disagreement noted."),
 'row_count':len(rows),'rows':rows}
json.dump(out,open(REPO/'data/bombelli-1792-raccolta.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
import collections
print('rows',len(rows),'with day',sum(1 for r in rows if r['coronation_date'] and len(r['coronation_date'])==10),
      'children',sum(1 for r in rows if r['child_date']),'costs',sum(1 for r in rows if r['crown_cost_scudi']),
      'undated',[r['title'] for r in rows if not r['coronation_date']])
print(collections.Counter(r['tomo'] for r in rows), collections.Counter(r['medium'] for r in rows))
